class Solution {
    long getRedundantSubstrings(String word, int a, int b) {
        HashMap<Long, Long> cnt = new HashMap<>();
        cnt.put(0L, 1L);
        long prefV = 0, prefC = 0, ans = 0;
        String vowels = "aeiou";
        for (char ch : word.toCharArray()) {
            if (vowels.indexOf(ch) >= 0) prefV++;
            else prefC++;
            long key = (long)(a - 1) * prefV + (long)(b - 1) * prefC;
            ans += cnt.getOrDefault(key, 0L);
            cnt.merge(key, 1L, Long::sum);
        }
        return ans;
    }
}

class Solution {
public:
    long long getRedundantSubstrings(string word, int a, int b) {
        unordered_map<long long, long long> cnt;
        cnt[0] = 1;
        long long prefV = 0, prefC = 0, ans = 0;
        string vowels = "aeiou";
        for (char ch : word) {
            if (vowels.find(ch) != string::npos) prefV++;
            else prefC++;
            long long key = (long long)(a - 1) * prefV + (long long)(b - 1) * prefC;
            ans += cnt[key];
            cnt[key]++;
        }
        return ans;
    }
};
